44	@@ -0,0 +1,1012 @@
45	+// SPDX-License-Identifier: Apache-2.0
46	+
47	+//! The OpenAI Responses API readers for the charge (SMA-769 D14, § 8.2): the request estimate,
48	+//! the non-stream completion estimate, and [`ResponsesUsageScanner`], which reads a COPY of a
49	+//! forwarded SSE stream. None of them changes a byte that reaches the client.
50	+//!
51	+//! A terminal event (`response.completed`, `response.incomplete`, `response.failed`) carries the
52	+//! whole response, so it can be many MiB. The scanner therefore never buffers a record. It reads
53	+//! `response.usage.total_tokens` with a byte-level JSON scan that holds only fixed state, so it has
54	+//! no record size limit (R-g).
55	+
56	+use serde_json::Value;
57	+
58	+use super::usage::{BodyUsage, FALLBACK_REQUEST_CAP, NON_TEXT_PART_TOKENS, bytes_to_tokens};
59	+
60	+/// The three event types whose `response.usage` is the charge (§ 8.2).
61	+const TERMINAL_TYPES: [&[u8]; 3] = [b"response.completed", b"response.incomplete", b"response.failed"];
62	+/// A `type` string longer than this is not a terminal type, and is not held.
63	+const MAX_TYPE_BYTES: usize = 64;
64	+/// `u64::MAX` has 20 digits. A longer `total_tokens` is not charged.
65	+const MAX_TOTAL_DIGITS: u32 = 20;
66	+/// serde_json 1.0's recursion limit: it accepts at most 127 nested containers. A deeper record is
67	+/// malformed here too, and the container stack fits in one `u128`.
68	+const MAX_DEPTH: u32 = 127;
69	+/// The longest key on the usage path, `total_tokens`. A longer key matches nothing.
70	+const MAX_KEY_BYTES: usize = 12;
71	+/// The key on the usage path at depth 1, 2 and 3.
72	+const USAGE_PATH: [&[u8]; 3] = [b"response", b"usage", b"total_tokens"];
73	+/// The key of the event type, at depth 1.
74	+const TYPE_KEY: &[u8] = b"type";
75	+
76	+/// Reads a copy of a forwarded Responses SSE stream (§ 8.2). The SSE rules are those of
77	+/// [`super::usage::UsageScanner`]: CR, LF and CRLF end a line, a `data:` line adds its value (one
78	+/// optional space removed), data lines of one record are joined with LF, and a blank line ends the
79	+/// record. Every complete data record that is not `[DONE]` and gives no usage adds one to the
80	+/// completion estimate. A terminal record that is well-formed JSON with a `u64` at
81	+/// `/response/usage/total_tokens` gives its total, and the last such total wins.
82	+///
83	+/// Every field is fixed size: the scanner holds no heap buffer, whatever the record size.
84	+#[derive(Debug, Default)]
85	+pub struct ResponsesUsageScanner {
86	+    /// The current line has at least one byte.
87	+    line_started: bool,
88	+    /// The last byte was CR: an LF right after it belongs to the same terminator.
89	+    after_cr: bool,
90	+    line: LineState,
91	+    /// The bytes of `data:` the current line has matched.
92	+    prefix_len: usize,
93	+    /// The current record has a data line.
94	+    has_data: bool,
95	+    /// The bytes of the record's data value, and its first six bytes (to match `[DONE]`).
96	+    data_len: usize,
97	+    head: [u8; 6],
98	+    json: JsonScan,
99	+    records: u64,
100	+    reported: Option<u64>,
101	+}
102	+
103	+#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
104	+enum LineState {
105	+    /// Reading the first five bytes.
106	+    #[default]
107	+    Prefix,
108	+    /// After `data:`: one space here is removed.
109	+    Space,
110	+    /// The data value.
111	+    Data,
112	+    /// Not a data line: the rest of the line is ignored.
113	+    Ignore,
114	+}
115	+
116	+impl ResponsesUsageScanner {
117	+    pub fn new() -> Self {
118	+        Self::default()
119	+    }
120	+
121	+    pub fn feed(&mut self, chunk: &[u8]) {
122	+        for &byte in chunk {
123	+            if self.after_cr {
124	+                self.after_cr = false;
125	+                if byte == b'\n' {
126	+                    continue;
127	+                }
128	+            }
129	+            match byte {
130	+                b'\n' => self.end_line(),
131	+                b'\r' => {
132	+                    self.end_line();
133	+                    self.after_cr = true;
134	+                }
135	+                _ => self.line_byte(byte),
136	+            }
137	+        }
138	+    }
139	+
140	+    /// The upstream stream ended, or failed. Close a pending line and a pending record, as a
141	+    /// blank line does (SMA-730). A second call does nothing.
142	+    pub fn finish(&mut self) {
143	+        self.feed(b"\n\n");
144	+    }
145	+
146	+    pub fn completion_records(&self) -> u64 {
147	+        self.records
148	+    }
149	+
150	+    pub fn reported_total(&self) -> Option<u64> {
151	+        self.reported
152	+    }
153	+
154	+    /// The bytes the scanner holds. It has no heap buffer, so this is its fixed size.
155	+    #[cfg(test)]
156	+    fn held_bytes(&self) -> usize {
157	+        std::mem::size_of::<Self>()
158	+    }
159	+
160	+    fn line_byte(&mut self, byte: u8) {
161	+        self.line_started = true;
162	+        match self.line {
163	+            LineState::Data => self.data_byte(byte),
164	+            LineState::Space => {
165	+                self.line = LineState::Data;
166	+                if byte != b' ' {
167	+                    self.data_byte(byte);
168	+                }
169	+            }
170	+            LineState::Prefix => {
171	+                const DATA: &[u8; 5] = b"data:";
172	+                if byte != DATA[self.prefix_len] {
173	+                    self.line = LineState::Ignore;
174	+                    return;
175	+                }
176	+                self.prefix_len += 1;
177	+                if self.prefix_len == DATA.len() {
178	+                    self.line = LineState::Space;
179	+                    if self.has_data {
180	+                        self.data_byte(b'\n');
181	+                    }
182	+                    self.has_data = true;
183	+                }
184	+            }
185	+            LineState::Ignore => {}
186	+        }
187	+    }
188	+
189	+    fn data_byte(&mut self, byte: u8) {
190	+        if let Some(slot) = self.head.get_mut(self.data_len) {
191	+            *slot = byte;
192	+        }
193	+        self.data_len = self.data_len.saturating_add(1);
194	+        self.json.feed(byte);
195	+    }
196	+
197	+    fn end_line(&mut self) {
198	+        if !self.line_started {
199	+            self.end_record();
200	+            return;
201	+        }
202	+        self.line_started = false;
203	+        self.line = LineState::Prefix;
204	+        self.prefix_len = 0;
205	+    }
206	+
207	+    fn end_record(&mut self) {
208	+        if self.has_data {
209	+            if self.data_len == self.head.len() && &self.head == b"[DONE]" {
210	+                // Not a completion record.
211	+            } else if let Some(total) = self.json.terminal_total() {
212	+                self.reported = Some(total);
213	+            } else {
214	+                self.records = self.records.saturating_add(1);
215	+            }
216	+        }
217	+        self.has_data = false;
218	+        self.data_len = 0;
219	+        self.json = JsonScan::default();
220	+    }
221	+}
222	+
223	+/// What the JSON grammar allows next.
224	+#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
225	+enum Expect {
226	+    /// Any value: the top level, after `:`, or after `,` in an array.
227	+    #[default]
228	+    Value,
229	+    /// A value or `]`: right after `[`.
230	+    ValueOrEnd,
231	+    /// A key or `}`: right after `{`.
232	+    KeyOrEnd,
233	+    /// A key: after `,` in an object.
234	+    Key,
235	+    Colon,
236	+    /// `,` or the end of the container.
237	+    CommaOrEnd,
238	+    /// The top-level value is complete. Only whitespace may follow.
239	+    Done,
240	+}
241	+
242	+/// The token being read.
243	+#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
244	+enum Token {
245	+    #[default]
246	+    None,
247	+    /// A string; `key` is true for an object key.
248	+    Str { key: bool, escape: Escape },
249	+    /// A number.
250	+    Number(NumberState),
251	+    /// `true`, `false` or `null`, with the bytes matched so far.
252	+    Literal { word: &'static [u8], matched: usize },
253	+}
254	+
255	+#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
256	+enum Escape {
257	+    #[default]
258	+    None,
259	+    /// After a backslash.
260	+    Backslash,
261	+    /// Inside `\uXXXX`, with the hex digits read so far.
262	+    Hex(u8),
263	+}
264	+
265	+/// The JSON number grammar: `-? (0 | [1-9][0-9]*) (. [0-9]+)? ([eE] [+-]? [0-9]+)?`.
266	+#[derive(Debug, Clone, Copy, PartialEq, Eq)]
267	+enum NumberState {
268	+    Minus,
269	+    Zero,
270	+    Int,
271	+    Dot,
272	+    Frac,
273	+    Exp,
274	+    ExpSign,
275	+    ExpDigits,
276	+}
277	+
278	+impl NumberState {
279	+    fn start(byte: u8) -> Option<Self> {
280	+        match byte {
281	+            b'-' => Some(Self::Minus),
282	+            b'0' => Some(Self::Zero),
283	+            b'1'..=b'9' => Some(Self::Int),
284	+            _ => None,
285	+        }
286	+    }
287	+
288	+    fn next(self, byte: u8) -> Option<Self> {
289	+        use NumberState::*;
290	+        match (self, byte) {
291	+            (Minus, b'0') => Some(Zero),
292	+            (Minus, b'1'..=b'9') | (Int, b'0'..=b'9') => Some(Int),
293	+            (Zero | Int, b'.') => Some(Dot),
294	+            (Dot | Frac, b'0'..=b'9') => Some(Frac),
295	+            (Zero | Int | Frac, b'e' | b'E') => Some(Exp),
296	+            (Exp, b'+' | b'-') => Some(ExpSign),
297	+            (Exp | ExpSign | ExpDigits, b'0'..=b'9') => Some(ExpDigits),
298	+            _ => None,
299	+        }
300	+    }
301	+
302	+    fn is_complete(self) -> bool {
303	+        matches!(self, Self::Zero | Self::Int | Self::Frac | Self::ExpDigits)
304	+    }
305	+}
306	+
307	+/// What the current value is captured as.
308	+#[derive(Debug, Default, Clone, Copy, PartialEq, Eq)]
309	+enum Capture {
310	+    #[default]
311	+    None,
312	+    /// The top-level `type` string.
313	+    Type,
314	+    /// The `/response/usage/total_tokens` number.
315	+    Total,
316	+}
317	+
318	+/// The captured `type` bytes (std has no `Default` for `[u8; 64]`).
319	+#[derive(Debug)]
320	+struct TypeBuf([u8; MAX_TYPE_BYTES]);
321	+
322	+impl Default for TypeBuf {
323	+    fn default() -> Self {
324	+        Self([0; MAX_TYPE_BYTES])
325	+    }
326	+}
327	+
328	+/// A byte-level JSON scan of one record's data value. It checks the JSON grammar (structure,
329	+/// strings, escapes, numbers and literals, depth up to 127) and captures the top-level `type` and
330	+/// `/response/usage/total_tokens`. The last value of a duplicate key wins, as in serde_json. It
331	+/// does not check UTF-8, and it does not decode escapes: a key or a `type` with an escape matches
332	+/// nothing, so the estimate applies.
333	+#[derive(Debug, Default)]
334	+struct JsonScan {
335	+    error: bool,
336	+    expect: Expect,
337	+    token: Token,
338	+    depth: u32,
339	+    /// Bit `d - 1` is set when the container at depth `d` is an object.
340	+    objects: u128,
341	+    /// The current key's bytes, up to `MAX_KEY_BYTES`.
342	+    key: [u8; MAX_KEY_BYTES],
343	+    key_len: usize,
344	+    /// The current key is longer than `MAX_KEY_BYTES` or has an escape.
345	+    key_other: bool,
346	+    /// The current key at depth 1, 2 and 3 is the key of `USAGE_PATH` at that depth.
347	+    on_path: [bool; 3],
348	+    /// The current key at depth 1 is `type`.
349	+    at_type: bool,
350	+    capture: Capture,
351	+    type_buf: TypeBuf,
352	+    type_len: usize,
353	+    /// The `type` string being captured is longer than `MAX_TYPE_BYTES` or has an escape.
354	+    type_other: bool,
355	+    /// The total being captured, or `None` when it is not a `u64`.
356	+    total_acc: Option<u64>,
357	+    total_digits: u32,
358	+    /// The last top-level `type` is a terminal type.
359	+    terminal: bool,
360	+    /// The last `/response/usage/total_tokens`, when it is a `u64`.
361	+    total: Option<u64>,
362	+}
363	+
364	+impl JsonScan {
365	+    /// The total to charge: the record is complete, well-formed JSON, its last top-level `type`
366	+    /// is terminal, and its last `/response/usage/total_tokens` is a `u64`.
367	+    fn terminal_total(&self) -> Option<u64> {
368	+        if self.error || self.expect != Expect::Done || self.token != Token::None || !self.terminal {
369	+            return None;
370	+        }
371	+        self.total
372	+    }
373	+
374	+    fn feed(&mut self, byte: u8) {
375	+        if self.error {
376	+            return;
377	+        }
378	+        match self.token {
379	+            Token::Str { key, escape } => self.string_byte(key, escape, byte),
380	+            Token::Number(state) => match state.next(byte) {
381	+                Some(next) => {
382	+                    self.token = REDACTED;
383	+                    self.total_byte(byte);
384	+                }
385	+                None if state.is_complete() => {
386	+                    self.end_scalar();
387	+                    self.structural(byte);
388	+                }
389	+                None => self.error = true,
390	+            },
391	+            Token::Literal { word, matched } => {
392	+                if matched == word.len() {
393	+                    self.end_scalar();
394	+                    self.structural(byte);
395	+                } else if word[matched] == byte {
396	+                    self.token = REDACTED { word, matched: matched + 1 };
397	+                } else {
398	+                    self.error = true;
399	+                }
400	+            }
401	+            Token::None => self.structural(byte),
402	+        }
403	+    }
404	+
405	+    fn string_byte(&mut self, key: bool, escape: Escape, byte: u8) {
406	+        let next = match escape {
407	+            Escape::Backslash => match byte {
408	+                b'"' | b'\\' | b'/' | b'b' | b'f' | b'n' | b'r' | b't' => Escape::None,
409	+                b'u' => Escape::Hex(0),
410	+                _ => return self.error = true,
411	+            },
412	+            Escape::Hex(n) if byte.is_ascii_hexdigit() => {
413	+                if n == 3 {
414	+                    Escape::None
415	+                } else {
416	+                    Escape::Hex(n + 1)
417	+                }
418	+            }
419	+            Escape::Hex(_) => return self.error = true,
420	+            Escape::None => match byte {
421	+                b'"' => return self.end_string(key),
422	+                b'\\' => {
423	+                    // An escaped key or type matches nothing.
424	+                    if key {
425	+                        self.key_other = true;
426	+                    } else if self.capture == Capture::Type {
427	+                        self.type_other = true;
428	+                    }
429	+                    Escape::Backslash
430	+                }
431	+                0x00..=0x1f => return self.error = true,
432	+                _ => {
433	+                    if key {
434	+                        self.key_byte(byte);
435	+                    } else if self.capture == Capture::Type {
436	+                        self.type_byte(byte);
437	+                    }
438	+                    Escape::None
439	+                }
440	+            },
441	+        };
442	+        self.token = REDACTED { key, escape: next };
443	+    }
444	+
445	+    fn key_byte(&mut self, byte: u8) {
446	+        match self.key.get_mut(self.key_len) {
447	+            Some(slot) => {
448	+                *slot = byte;
449	+                self.key_len += 1;
450	+            }
451	+            None => self.key_other = true,
452	+        }
453	+    }
454	+
455	+    fn type_byte(&mut self, byte: u8) {
456	+        match self.type_buf.0.get_mut(self.type_len) {
457	+            Some(slot) => {
458	+                *slot = byte;
459	+                self.type_len += 1;
460	+            }
461	+            None => self.type_other = true,
462	+        }
463	+    }
464	+
465	+    fn total_byte(&mut self, byte: u8) {
466	+        if self.capture != Capture::Total {
467	+            return;
468	+        }
469	+        // Only plain digits: a sign, a fraction or an exponent is not a token count.
470	+        self.total_digits = self.total_digits.saturating_add(1);
471	+        self.total_acc = match (self.total_acc, byte) {
472	+            (Some(acc), b'0'..=b'9') if self.total_digits <= MAX_TOTAL_DIGITS => acc.checked_mul(10).and_then(|v| v.checked_add(u64::from(byte - b'0'))),
473	+            _ => None,
474	+        };
475	+    }
476	+
477	+    fn end_string(&mut self, key: bool) {
478	+        self.token = REDACTED;
479	+        if key {
480	+            let name = &self.key[..self.key_len];
481	+            let matched = |want: &[u8]| !self.key_other && name == want;
482	+            match self.depth {
483	+                1 => {
484	+                    self.on_path[0] = matched(USAGE_PATH[0]);
485	+                    self.at_type = matched(TYPE_KEY);
486	+                }
487	+                2 => self.on_path[1] = matched(USAGE_PATH[1]),
488	+                3 => self.on_path[2] = matched(USAGE_PATH[2]),
489	+                _ => {}
490	+            }
491	+            self.expect = Expect::Colon;
492	+            return;
493	+        }
494	+        if self.capture == Capture::Type {
495	+            let value = &self.type_buf.0[..self.type_len];
496	+            self.terminal = !self.type_other && TERMINAL_TYPES.contains(&value);
497	+        }
498	+        self.end_value();
499	+    }
500	+
501	+    fn end_scalar(&mut self) {
502	+        self.token = REDACTED;
503	+        if self.capture == Capture::Total {
504	+            self.total = self.total_acc;
505	+        }
506	+        self.end_value();
507	+    }
508	+
509	+    /// A value is complete.
510	+    fn end_value(&mut self) {
511	+        self.capture = Capture::None;
512	+        self.expect = if self.depth == 0 { Expect::Done } else { Expect::CommaOrEnd };
513	+    }
514	+
515	+    fn in_object(&self) -> bool {
516	+        self.depth > 0 && self.objects & (1u128 << (self.depth - 1)) != 0
517	+    }
518	+
519	+    /// A value begins in the current container. Reset what it replaces (the last duplicate key
520	+    /// wins) and pick what to capture. A value in an array matches nothing: `open` clears the
521	+    /// key flags of an array's depth, and only an object key sets them again.
522	+    fn begin_value(&mut self, byte: u8) {
523	+        let on_path = self.on_path;
524	+        let path = |n: usize| on_path[..n].iter().all(|&on| on);
525	+        match self.depth {
526	+            1 if self.at_type => {
527	+                self.terminal = false;
528	+                if byte == b'"' {
529	+                    self.capture = Capture::Type;
530	+                    self.type_len = 0;
531	+                    self.type_other = false;
532	+                }
533	+            }
534	+            1 | 2 if path(self.depth as usize) => self.total = None,
535	+            3 if path(3) => {
536	+                self.total = None;
537	+                if byte.is_ascii_digit() {
538	+                    self.capture = Capture::Total;
539	+                    self.total_acc = Some(0);
540	+                    self.total_digits = 0;
541	+                }
542	+            }
543	+            _ => {}
544	+        }
545	+    }
546	+
547	+    fn open(&mut self, object: bool) {
548	+        if self.depth >= MAX_DEPTH {
549	+            self.error = true;
550	+            return;
551	+        }
552	+        self.depth += 1;
553	+        let bit = 1u128 << (self.depth - 1);
554	+        if object {
555	+            self.objects |= bit;
556	+            self.expect = Expect::KeyOrEnd;
557	+        } else {
558	+            self.objects &= !bit;
559	+            self.expect = Expect::ValueOrEnd;
560	+        }
561	+        if let Some(on) = self.on_path.get_mut(self.depth as usize - 1) {
562	+            *on = false;
563	+        }
564	+        if self.depth == 1 {
565	+            self.at_type = false;
566	+        }
567	+    }
568	+
569	+    fn close(&mut self, object: bool) {
570	+        if self.depth == 0 || self.in_object() != object {
571	+            self.error = true;
572	+            return;
573	+        }
574	+        self.depth -= 1;
575	+        self.end_value();
576	+    }
577	+
578	+    fn start_value(&mut self, byte: u8) {
579	+        self.begin_value(byte);
580	+        match byte {
581	+            b'{' => self.open(true),
582	+            b'[' => self.open(false),
583	+            b'"' => self.token = REDACTED { key: false, escape: Escape::None },
584	+            b't' => self.token = REDACTED { word: b"true", matched: 1 },
585	+            b'f' => self.token = REDACTED { word: b"false", matched: 1 },
586	+            b'n' => self.token = REDACTED { word: b"null", matched: 1 },
587	+            _ => match NumberState::start(byte) {
588	+                Some(state) => {
589	+                    self.token = REDACTED;
590	+                    self.total_byte(byte);
591	+                }
592	+                None => self.error = true,
593	+            },
594	+        }
595	+    }
596	+
597	+    /// A byte outside a string or a scalar.
598	+    fn structural(&mut self, byte: u8) {
599	+        if matches!(byte, b' ' | b'\t' | b'\n' | b'\r') {
600	+            return;
601	+        }
602	+        match (self.expect, byte) {
603	+            (Expect::ValueOrEnd, b']') => self.close(false),
604	+            (Expect::Value | Expect::ValueOrEnd, _) => self.start_value(byte),
605	+            (Expect::KeyOrEnd, b'}') => self.close(true),
606	+            (Expect::KeyOrEnd | Expect::Key, b'"') => {
607	+                self.key_len = 0;
608	+                self.key_other = false;
609	+                self.token = REDACTED { key: true, escape: Escape::None };
610	+            }
611	+            (Expect::Colon, b':') => self.expect = Expect::Value,
612	+            (Expect::CommaOrEnd, b',') => self.expect = if self.in_object() { Expect::Key } else { Expect::Value },
613	+            (Expect::CommaOrEnd, b'}') => self.close(true),
614	+            (Expect::CommaOrEnd, b']') => self.close(false),
615	+            _ => self.error = true,
616	+        }
617	+    }
618	+}
