620	+/// A non-stream `2xx` Responses body (§ 8.2): `usage.total_tokens`, or the completion estimate
621	+/// from `output[].content[].text`, `output[].arguments` and `output[].input` by the chat rule.
622	+pub fn non_stream_usage(body: &[u8]) -> BodyUsage {
623	+    let Ok(value) = serde_json::from_slice::<Value>(body) else {
624	+        return BodyUsage::Completion(0);
625	+    };
626	+    if let Some(total) = value.pointer("/usage/total_tokens").and_then(Value::as_u64) {
627	+        return BodyUsage::Reported(total);
628	+    }
629	+    let mut bytes = 0usize;
630	+    for item in value.get("output").and_then(Value::as_array).into_iter().flatten() {
631	+        for part in item.get("content").and_then(Value::as_array).into_iter().flatten() {
632	+            if let Some(text) = part.get("text").and_then(Value::as_str) {
633	+                bytes = bytes.saturating_add(text.len());
634	+            }
635	+        }
636	+        for field in ["arguments", "input"] {
637	+            if let Some(text) = item.get(field).and_then(Value::as_str) {
638	+                bytes = bytes.saturating_add(text.len());
639	+            }
640	+        }
641	+    }
642	+    BodyUsage::Completion(bytes_to_tokens(bytes))
643	+}
644	+
645	+/// The request estimate by the chat rule (§ 8.2, SMA-677 D14): `ceil(text_bytes / 4)` over
646	+/// `instructions`, a string `input`, and per `input` item its `content` (a string, or the `text`
647	+/// of `input_text` parts, plus 85 per other typed part), `arguments`, `input` and `output`
648	+/// strings. A `null` or absent field counts 0. Any other shape falls back to `ceil(body_len / 4)`,
649	+/// capped at 32768.
650	+pub fn request_tokens_estimate(v: &Value, body_len: usize) -> u64 {
651	+    let fallback = bytes_to_tokens(body_len).min(FALLBACK_REQUEST_CAP);
652	+    let mut text_bytes = 0usize;
653	+    let mut other_parts = 0u64;
654	+    if !add_text(v.get("instructions"), &mut text_bytes) {
655	+        return fallback;
656	+    }
657	+    match v.get("input") {
658	+        Some(Value::Array(items)) => {
659	+            for item in items {
660	+                let Some(item) = item.as_object() else { return fallback };
661	+                for field in ["arguments", "input", "output"] {
662	+                    if !add_text(item.get(field), &mut text_bytes) {
663	+                        return fallback;
664	+                    }
665	+                }
666	+                match item.get("content") {
667	+                    Some(Value::Array(parts)) => {
668	+                        for part in parts {
669	+                            match (part.get("type").and_then(Value::as_str), part.get("text").and_then(Value::as_str)) {
670	+                                (Some("input_text"), Some(text)) => text_bytes = text_bytes.saturating_add(text.len()),
671	+                                (Some(_), _) => other_parts = other_parts.saturating_add(1),
672	+                                (None, _) => return fallback,
673	+                            }
674	+                        }
675	+                    }
676	+                    content => {
677	+                        if !add_text(content, &mut text_bytes) {
678	+                            return fallback;
679	+                        }
680	+                    }
681	+                }
682	+            }
683	+        }
684	+        input => {
685	+            if !add_text(input, &mut text_bytes) {
686	+                return fallback;
687	+            }
688	+        }
689	+    }
690	+    bytes_to_tokens(text_bytes).saturating_add(other_parts.saturating_mul(NON_TEXT_PART_TOKENS))
691	+}
692	+
693	+/// Adds the bytes of a string field. A `null` or absent field adds 0. Any other shape returns
694	+/// `false`: the caller uses the fallback.
695	+fn add_text(field: Option<&Value>, text_bytes: &mut usize) -> bool {
696	+    match field {
697	+        None | Some(Value::Null) => true,
698	+        Some(Value::String(text)) => {
699	+            *text_bytes = text_bytes.saturating_add(text.len());
700	+            true
701	+        }
702	+        Some(_) => false,
703	+    }
704	+}
