+    /// One SSE event with the real `event:` line.
+    fn event(data: &str) -> String {
+        let kind = serde_json::from_str::<Value>(data)
+            .ok()
+            .and_then(|v| v.get("type").and_then(Value::as_str).map(str::to_owned))
+            .unwrap_or_default();
